<style>
.folder-resource-toolbar{display:flex;align-items:center;gap:12px;margin:18px 0;min-width:0;flex-wrap:wrap}
.folder-search{display:flex;align-items:center;gap:12px;flex:1;min-width:200px;padding:12px 15px;border:1px solid var(--border-glass,#e2e8f0);background:var(--bg-card,#fff);border-radius:13px;color:var(--text-muted)}
.folder-search:focus-within{border-color:var(--accent,#365ce9);box-shadow:0 0 0 3px #365ce912}.folder-search input{width:100%;min-width:0;background:transparent;border:0;outline:0;color:var(--text-primary);font-size:13px;padding:0;box-shadow:none}
.folder-multi-filter{position:relative;flex:none}.folder-filter-trigger{display:flex;align-items:center;gap:10px;border:1px solid var(--border-glass,#e2e8f0);background:var(--bg-card,#fff);border-radius:13px;padding:12px 14px;font-size:12px;font-weight:600;color:var(--text-secondary)}.folder-filter-trigger[aria-expanded=true]{border-color:#5275ff;background:#5275ff0a}.folder-filter-trigger>i:last-child{font-size:10px;color:var(--text-muted)}.folder-filter-count,.folder-section-badge{border-radius:7px;padding:3px 7px;background:#5275ff0c;color:var(--accent,#365ce9);font-size:11px;white-space:nowrap}
.folder-section-badge{display:flex;align-items:center;gap:7px;padding:7px 10px}.folder-filter-menu{position:absolute;right:0;top:calc(100% + 9px);width:300px;z-index:50;background:var(--bg-card,#fff);border:1px solid var(--border-glass,#e2e8f0);border-radius:16px;padding:14px;box-shadow:0 18px 48px #0f172a1a}.folder-filter-menu-head,.folder-filter-quick{display:flex;align-items:center;justify-content:space-between;gap:10px}.folder-filter-menu-head{font-size:13px;margin-bottom:12px}.folder-filter-menu-head button{width:28px;height:28px;border-radius:8px;background:var(--bg-glass-light,#f1f5f9);color:var(--text-muted)}.folder-filter-quick{font-size:11px;padding-bottom:12px;border-bottom:1px solid var(--border-glass,#e2e8f0);color:var(--accent,#365ce9)}.folder-filter-menu fieldset{max-height:min(300px,45vh);overflow:auto;margin:8px 0}.folder-filter-option{display:flex;gap:10px;align-items:center;padding:10px 9px;border-radius:9px;font-size:12px;cursor:pointer}.folder-filter-option:hover{background:#5275ff08}.folder-filter-option span{flex:1}.folder-filter-option small{color:var(--text-muted);font-size:11px}.folder-filter-option input,.folder-picker-option input{accent-color:#5275ff;width:16px;height:16px;flex:none}.folder-filter-menu>p{font-size:10px;color:var(--text-muted);line-height:1.6;margin-top:10px}
.folder-selected-chips{display:flex;flex-wrap:wrap;gap:7px;margin:12px 0}.folder-selected-chips .form-chip{font-size:11px;padding:6px 10px;display:flex;align-items:center;gap:8px}.folder-clear-link{font-size:11px;color:var(--text-muted);padding:5px}.folder-resource-list{display:grid;gap:10px;margin-top:18px}.folder-resource-row{display:flex;align-items:center;gap:15px;padding:18px;border:1px solid var(--border-glass,#e2e8f0);border-radius:15px;background:var(--bg-card,#fff);transition:border-color .15s,box-shadow .15s}.folder-resource-row:hover{border-color:#5275ff55;box-shadow:0 4px 18px #365ce90b}.folder-resource-icon{width:46px;height:46px;flex:none;border-radius:13px;display:grid;place-items:center;background:linear-gradient(135deg,#5275ff12,#9b68ee10);color:#5275ff;font-size:18px}.folder-resource-icon img{border-radius:8px;object-fit:contain}.folder-resource-copy{flex:1;min-width:0}.folder-resource-copy strong{display:block;font-size:14px;line-height:1.6;overflow-wrap:anywhere}.folder-resource-copy small{display:block;color:var(--text-muted);font-size:11px;margin-top:4px}.folder-resource-type{font-size:10px;letter-spacing:.045em;color:var(--text-muted);font-weight:600}.folder-resource-open{font-size:11px;display:flex;gap:9px;align-items:center;color:var(--text-muted);flex:none}.folder-filter-empty{display:grid;justify-items:center;gap:12px;padding:32px;text-align:center;color:var(--text-muted);font-size:13px}.folder-filter-empty>i{font-size:24px;color:#5275ff}.folder-filter-empty strong{color:var(--text-primary)}
.folder-picker-panel{border:1px solid var(--border-glass,#e2e8f0);border-radius:15px;background:var(--bg-card,#fff)}.folder-picker-panel>summary{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:16px;cursor:pointer;list-style:none;font-weight:600;font-size:13px}.folder-picker-panel>summary::-webkit-details-marker{display:none}.folder-picker-panel>summary>span:first-child{display:flex;gap:9px;align-items:center}.folder-picker-summary{font-size:11px;color:var(--accent,#365ce9);white-space:nowrap}.folder-picker-summary i{margin-left:10px;font-size:10px}.folder-picker-body{padding:0 16px 16px;border-top:1px solid var(--border-glass,#e2e8f0)}.folder-picker-actions{display:flex;flex-wrap:wrap;gap:8px;align-items:center;justify-content:space-between;font-size:11px;color:var(--text-muted);margin-bottom:12px}.folder-picker-actions>div{display:flex;gap:14px}.folder-picker-actions button{color:var(--accent,#365ce9);font-weight:600}.folder-picker-actions button:disabled{opacity:.4;cursor:not-allowed}.folder-picker-list{max-height:320px;overflow:auto;display:grid;gap:7px}.folder-picker-option{display:flex;gap:10px;align-items:center;padding:12px;border:1px solid var(--border-glass,#e2e8f0);border-radius:10px;cursor:pointer}.folder-picker-option strong{font-size:12px;overflow-wrap:anywhere}.folder-picker-option.is-selected{border-color:#5275ff55;background:#5275ff08}.folder-picker-option .folder-resource-type{min-width:40px}
.folder-marketing-metrics .notes-metric{min-height:172px;padding-right:110px;border:1px solid #ffffff2e;box-shadow:0 10px 25px #365ce910}.folder-marketing-metrics .notes-metric>span{font-size:13px;font-weight:600}.folder-marketing-metrics .stat-art{position:absolute;right:20px;top:38px;width:78px;height:78px;opacity:.85}.folder-campaign-empty{display:grid;grid-template-columns:auto minmax(0,1fr);align-items:center;gap:28px;padding:30px!important;background:linear-gradient(120deg,#5275ff06,transparent);min-height:230px}.folder-campaign-empty h2{margin:5px 0 10px}.folder-campaign-empty .notes-hint{max-width:68ch;line-height:1.8}.folder-campaign-orbit{width:108px;height:108px;border:1px solid #5275ff22;border-radius:50%;display:grid;place-items:center;background:radial-gradient(circle,#5275ff16,transparent 70%);color:#5275ff;font-size:32px;box-shadow:0 0 0 12px #5275ff04}.folder-campaign-flow{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin:18px 0;font-size:11px;color:var(--text-muted)}.folder-campaign-flow span{padding:6px 9px;border:1px solid var(--border-glass,#e2e8f0);border-radius:8px;background:var(--bg-card,#fff)}.folder-campaign-flow i{font-size:9px;opacity:.5}.folder-workflow-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.folder-workflow-grid>a{padding:20px;border:1px solid var(--border-glass,#e2e8f0);border-radius:14px;display:grid;gap:10px;transition:border-color .15s}.folder-workflow-grid>a:hover{border-color:#5275ff55}.folder-workflow-grid strong{font-size:13px}.folder-workflow-grid p{font-size:12px;line-height:1.7;color:var(--text-muted)}.folder-workflow-grid>a>span:last-child{font-size:11px;font-weight:600;color:var(--accent,#365ce9);align-self:end}.folder-marketing-card{border:1px solid var(--border-glass,#e2e8f0);border-radius:14px;padding:20px;background:var(--bg-card,#fff)}.folder-marketing-card h3{font-size:16px;font-weight:700;margin-bottom:10px}.folder-marketing-open{display:flex;gap:8px;align-items:center;justify-content:space-between;font-size:12px;color:var(--accent,#365ce9);border-top:1px solid var(--border-glass,#e2e8f0);padding-top:14px;margin-top:18px;font-weight:600}.folder-campaign-results{display:flex;gap:20px;margin-top:18px;font-size:10px;color:var(--text-muted)}.folder-campaign-results strong{display:block;font-size:18px;color:var(--text-primary);margin-bottom:4px}
@media(max-width:640px){.folder-resource-toolbar{gap:9px}.folder-search,.folder-multi-filter{width:100%;min-width:0}.folder-filter-trigger{width:100%;justify-content:space-between}.folder-filter-menu{position:relative;top:auto;right:auto;margin-top:9px;width:100%;max-width:100%;padding:12px}.folder-resource-row{padding:14px;gap:12px}.folder-resource-open{font-size:0}.folder-resource-open i{font-size:12px}.folder-resource-icon{width:38px;height:38px}.folder-resource-copy strong{font-size:13px}.folder-picker-option{flex-wrap:wrap}.folder-workflow-grid{grid-template-columns:1fr}.folder-campaign-empty{grid-template-columns:1fr;padding:22px!important;gap:20px}.folder-campaign-orbit{width:68px;height:68px;font-size:23px;margin-left:8px}.folder-campaign-flow{gap:7px}.folder-marketing-metrics .notes-metric{min-height:145px}.folder-panel-head{flex-wrap:wrap}.folder-picker-summary{font-size:10px}}
